    """Return a closed chain using every domino, or None if none exists."""
    adjacency = {}
    used = []
    for edge_id, (left, right) in enumerate(dominoes):
        adjacency.setdefault(left, []).append((right, edge_id))
        adjacency.setdefault(right, []).append((left, edge_id))
        used.append(False)

    if not used:
        return []
    if any(len(edges) % 2 for edges in adjacency.values()):
        return None

    # Hierholzer's algorithm: traverse edges, then splice cycles on backtracking.
    # Unique edge IDs keep duplicate stones (and doubles) distinct.
    stack = [next(iter(adjacency))]
    circuit = []
    while stack:
        vertex = stack[-1]
        edges = adjacency[vertex]
        while edges and used[edges[-1][1]]:
            edges.pop()
        if edges:
            neighbor, edge_id = edges.pop()
            used[edge_id] = True
            stack.append(neighbor)
        else:
            circuit.append(stack.pop())

    # Even degrees are not enough: all stones must be in one component.
    if len(circuit) != len(used) + 1:
        return None

    circuit.reverse()
    return list(zip(circuit, circuit[1:]))
