{"content":"import unittest
from collections import Counter

from dominoes import can_chain


class DominoesTest(unittest.TestCase):
    def assert_valid_chain(self, dominoes):
        original = list(dominoes)
        chain = can_chain(dominoes)
        self.assertIsNotNone(chain)
        self.assertEqual(dominoes, original, "Input must not be mutated")
        self.assertEqual(
            Counter(tuple(sorted(stone)) for stone in chain),
            Counter(tuple(sorted(stone)) for stone in dominoes),
        )
        if chain:
            for current, following in zip(chain, chain[1:] + chain[:1]):
                self.assertEqual(current[1], following[0])

    def test_empty(self):
        self.assertEqual(can_chain([]), [])

    def test_single_stone(self):
        self.assert_valid_chain([(3, 3)])
        self.assertIsNone(can_chain([(1, 2)]))

    def test_example_requires_flipping(self):
        self.assert_valid_chain([(2, 1), (2, 3), (1, 3)])

    def test_open_chain_is_rejected(self):
        self.assertIsNone(can_chain([(1, 2), (4, 1), (2, 3)]))

    def test_duplicates_and_doubles(self):
        self.assert_valid_chain([(1, 2), (1, 2), (1, 1), (2, 2)])
        self.assert_valid_chain([(0, 0), (0, 0), (0, 0)])

    def test_disconnected_even_degree_components(self):
        self.assertIsNone(can_chain([(1, 2), (2, 1), (3, 4), (4, 3)]))
        self.assertIsNone(can_chain([(1, 1), (2, 2)]))

    def test_cycles_are_spliced(self):
        self.assert_valid_chain(
            [(0, 1), (1, 2), (2, 0), (1, 3), (3, 4), (4, 1)]
        )

    def test_long_chain_does_not_need_recursion(self):
        self.assert_valid_chain([(n, (n + 1) % 2000) for n in range(2000)])


if __name__ == "__main__":
    unittest.main()
